type BrandMarkProps = {
  logoUrl?: string | null
  className?: string
  imageClassName?: string
  variant?: "auto" | "light" | "dark" | "sidebar" | "login" | "favicon"
}

export function BrandLogo({
  className,
  imageClassName,
  variant = "auto",
}: BrandMarkProps) {
  const isFullLogo = variant === "login"
  const navyClass =
    variant === "sidebar"
      ? "text-cyan-200"
      : variant === "dark" || variant === "login"
        ? "text-[#d9e8ff]"
        : variant === "light" || variant === "favicon"
          ? "text-[#061f4b]"
          : "text-[#061f4b] dark:text-[#d9e8ff]"
  const goldClass =
    variant === "dark" || variant === "sidebar" || variant === "login"
      ? "text-[#f4bd45]"
      : variant === "light" || variant === "favicon"
        ? "text-[#e4a520]"
        : "text-[#e4a520] dark:text-[#f4bd45]"

  return (
    <span
      role="img"
      aria-label={`${hostelConfig.name} — S-HOSTEL — Stay, Study, Succeed`}
      className={cn(
        "brand-logo-container relative flex size-10 shrink-0 items-center justify-center",
        className,
        "!border-0 !bg-transparent !shadow-none"
      )}
      style={{ containerName: "brand-logo", containerType: "inline-size" }}
    >
      {variant === "auto" ? (
        <style>{`
          .brand-logo-container .brand-logo-full { display: none; }
          @container brand-logo (min-width: 5rem) {
            .brand-logo-container .brand-logo-icon { display: none; }
            .brand-logo-container .brand-logo-full { display: block; }
          }
        `}</style>
      ) : null}

      {!isFullLogo ? (
        <BrandSvg
          paths={BRAND_ICON_PATHS}
          className={cn("brand-logo-icon", imageClassName)}
          navyClass={navyClass}
          goldClass={goldClass}
        />
      ) : null}

      {isFullLogo || variant === "auto" ? (
        <BrandSvg
          paths={BRAND_FULL_PATHS}
          className={cn("brand-logo-full", imageClassName)}
          navyClass={navyClass}
          goldClass={goldClass}
        />
      ) : null}
    </span>
  )
}

export const BrandMark = BrandLogo

function BrandSvg({
  paths,
  className,
  navyClass,
  goldClass,
}: {
  paths: { viewBox: string; navy: string; gold: string }
  className?: string
  navyClass: string
  goldClass: string
}) {
  return (
    <svg
      viewBox={paths.viewBox}
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      className={cn("size-full overflow-visible", className)}
      aria-hidden="true"
    >
      <path
        d={paths.navy}
        fill="currentColor"
        fillRule="evenodd"
        className={navyClass}
      />
      <path
        d={paths.gold}
        fill="currentColor"
        fillRule="evenodd"
        className={goldClass}
      />
    </svg>
  )
}
